import { describe, expect, test, afterEach } from 'vitest';
import { render, cleanup } from '@testing-library/svelte';
import HatchDefs from './HatchDefs.svelte';
import { hatchUnitPt, hatchPatternIds, previewSegments, PT_TO_CSS } from '$lib/core/hatchPatterns';
import data from '$lib/core/hatchPatterns.json';

// ERR-007 / BUG-015 "honest UI": the on-screen hatch preview is drawn from the SAME pattern
// parameters (and the Rust-clipped tile) that Studio save uses, so what you see is what is saved.
// hatchPatterns.json is generated by crates/lpdf-geom (tests/studio_golden.rs checks it).

afterEach(() => cleanup());

// Every pattern id the property pill offers as a line hatch (PropertyPill.svelte HATCH_PATTERNS).
const UI_LINE_PATTERNS = [
  'diagonal-steel',
  'crosshatch',
  'concrete',
  'timber',
  'tiling',
  'masonry',
  'earth',
  'insulation'
];

function tileOf(container: HTMLElement, id: string) {
  const pat = container.querySelector(`pattern#hatch-${id}`);
  expect(pat, `pattern hatch-${id}`).not.toBeNull();
  return pat as Element;
}

function lines(pat: Element) {
  return [...pat.querySelectorAll('line')].map((l) =>
    ['x1', 'y1', 'x2', 'y2'].map((a) => Number(l.getAttribute(a)))
  );
}

describe('HatchDefs preview', () => {
  test('every UI hatch pattern has a preview tile', () => {
    const { container } = render(HatchDefs, { scale: 1 });
    for (const id of UI_LINE_PATTERNS) expect(tileOf(container, id)).toBeTruthy();
    expect(hatchPatternIds()).toEqual(expect.arrayContaining(UI_LINE_PATTERNS));
  });

  test('the preview draws exactly the Rust tile, scaled like the saved hatch', () => {
    for (const scale of [1, 2, 0.5]) {
      const { container, unmount } = render(HatchDefs, { scale });
      const px = hatchUnitPt(scale) * PT_TO_CSS;
      for (const p of data.patterns) {
        const pat = tileOf(container, p.id);
        expect(Number(pat.getAttribute('width'))).toBeCloseTo(data.tileCells * px, 6);
        expect(Number(pat.getAttribute('height'))).toBeCloseTo(data.tileCells * px, 6);
        const got = lines(pat);
        const want = previewSegments(p);
        expect(got.length, `${p.id} segment count`).toBe(want.length);
        want.forEach((seg, i) => {
          seg.forEach((v, k) => expect(got[i][k]).toBeCloseTo(v * px, 6));
        });
        // The Rust tile comes first, untouched.
        p.tile.forEach((seg, i) => expect(want[i]).toEqual(seg));
      }
      unmount();
    }
  });

  test('the preview is mirrored so screen y-down matches PDF y-up', () => {
    const { container } = render(HatchDefs, { scale: 1 });
    expect(tileOf(container, 'diagonal-steel').getAttribute('patternTransform')).toContain(
      'scale(1 -1)'
    );
  });

  test('only lines on the lower/left tile edge are repeated on the opposite edge', () => {
    for (const p of data.patterns) {
      const extra = previewSegments(p).slice(p.tile.length);
      const onEdge = p.tile.filter(
        ([x1, y1, x2, y2]) => (y1 === 0 && y2 === 0) || (x1 === 0 && x2 === 0)
      );
      expect(extra.length, p.id).toBe(onEdge.length);
    }
  });

  test('scale uses the same clamp and 3 pt minimum as the saved hatch', () => {
    expect(hatchUnitPt(1)).toBe(8);
    expect(hatchUnitPt(2)).toBe(16);
    expect(hatchUnitPt(10)).toBe(32);
    expect(hatchUnitPt(0.1)).toBe(3);
    expect(hatchUnitPt(Number.NaN)).toBe(8);
  });

  test('every pattern preview is different', () => {
    const { container } = render(HatchDefs, { scale: 1 });
    const seen = new Map<string, string>();
    for (const p of data.patterns) {
      const key = JSON.stringify(lines(tileOf(container, p.id)));
      expect(seen.get(key), `${p.id} looks like ${seen.get(key)}`).toBeUndefined();
      seen.set(key, p.id);
    }
  });

  test('the redaction warning pattern is still there', () => {
    const { container } = render(HatchDefs, { scale: 1 });
    expect(container.querySelector('pattern#hatch-redact-danger')).not.toBeNull();
  });
});
